-- Khai báo đa ngôn ngữ cho /cost/material-product & ProductMaterialInfo / ProductMaterialInfoAll
-- Chạy trên database am_manager, bảng t_message_info.
-- Tương thích MySQL 5.6/8.4. Nếu KEY có UNIQUE/PRIMARY KEY thì UPDATE giá trị bản dịch đã tồn tại.
ON DUPLICATE KEY UPDATE
  `KOR` = VALUES(`KOR`),
  `ENG` = VALUES(`ENG`),
  `VIET` = VALUES(`VIET`),
  `JPN` = VALUES(`JPN`),
  `THA` = VALUES(`THA`),
  `CHN` = VALUES(`CHN`),
  `COMMENT` = VALUES(`COMMENT`),
  `LAST_MIDOFY_DATE` = NOW();

SELECT `KEY`, `VIET`, `ENG`, `KOR`, `JPN`, `THA`, `CHN`
FROM `t_message_info`
WHERE `KEY` LIKE 'PM\\_%' OR `KEY` = 'PRODUCT_MATERIAL_IMPORT_ALL'
ORDER BY `KEY`;
